            "tab_index": tab_index,
            "url": page.url,
            "title": page.title(),
            "http_status": http_status,
        }
        if workspace_name:
            result["workspace"] = workspace_name
        _sync_workspace_from_browser(
            workspace_name=workspace_name,
            ws=ws,
            browser=browser,
            session_id=session_id,
            history_entry={
                "type": "new-tab",
                "tab_index": tab_index,
                "url": page.url,
                "title": page.title(),
            },
            result=result,
        )
        output_json(result)
    except Exception as e:
        output_error(f"Failed to open a new tab: {e}")
        sys.exit(1)
    finally:
        try:
            browser.close()
        except Exception:
            pass
        try:
            pw.stop()
        except Exception:
