                })
                _save_workspace(str(args.workspace), ws)
                result["workspace_tabs_count"] = len(tabs)
            except Exception as e:
                result["workspace_update_error"] = str(e)

        output_json(result)
    except Exception as e:
        output_error(f"Failed to get cookies: {e}")
        sys.exit(1)
    finally:
        try:
            browser.close()
        except Exception:
            pass
        try:
            pw.stop()
        except Exception:
            pass


