    }
    if getattr(args, "workspace", None):
        result["workspace"] = str(args.workspace)
    if ws is not None and getattr(args, "workspace", None):
        try:
            _append_ws_history(ws, {"ts": _utc_now_iso(), "type": "get-downloads", "session_id": session_id})
